# Post definitions for generate_weight_telehealth_blogs.py
from __future__ import annotations


def post(
    kind: str,
    slug: str,
    title: str,
    description: str,
    og_title: str,
    h1: str,
    lead: str,
    sections: list[tuple[str, list[str]]],
    faqs: list[tuple[str, str]],
    related: list[tuple[str, str]],
) -> dict:
    parts = []
    for h2, paras in sections:
        parts.append(f"            <h2>{h2}</h2>")
        for p in paras:
            parts.append(f"            <p>{p}</p>")
    body = "\n".join(parts)
    return {
        "kind": kind,
        "slug": slug,
        "title": title,
        "description": description,
        "og_title": og_title,
        "h1": h1,
        "lead": lead,
        "body": body,
        "faqs": faqs,
        "related": related,
    }


